INSERT IGNORE INTO `products` (`id`, `name`, `type`, `description`, `price`, `status`, `image`, `image_path`, `created_at`, `updated_at`, `slug`, `stock_status`, `featured`, `sort_order`, `whatsapp_number`, `stock_quantity`, `product_type`, `regular_price`, `sell_price`, `meta_title`, `meta_description`, `category_id`, `overview`, `usage`, `faqs`) VALUES ('e978fe07-f215-415b-a49d-02af598e3ff0', 'Hair oil', 'OIL', 'Hair oil for hair use only ', '2000', 'Published', '/products/hair-oil-migrated.png', '3a096a33-c682-425f-863a-62041a90c3aa.png', '2026-10-19 06:28:04', '2026-10-20 02:11:12', 'hair-oil-e978fe07', 'In Stock', 1, 1, '923239992203', 20, 'simple', '2000.00', '2000.00', 'Hair oil | Baba Hakeem', 'Hair oil for hair use only', NULL, NULL, NULL, '[{"question":"How should I apply Hair oil?","answer":"Apply it only as described on the label. For a new topical product, test a small area first and stop using it if irritation occurs."},{"question":"How often should I apply it?","answer":"Follow the frequency stated on the product packaging. Using more than directed is not recommended."},{"question":"Can I use it if I have sensitive skin or a health condition?","answer":"Check the complete ingredient list first. For topical products, test a small area of skin before regular use. If you have a health condition, take medication, are pregnant, or are breastfeeding, consult a qualified healthcare professional."},{"question":"How should I store this product?","answer":"Keep the container closed and store it in a cool, dry place away from direct sunlight. Keep it out of reach of children."}]');
